/**
 * LAYER: Interface
 * Contains: Seo — all head metadata for a docs page (title, description, canonical,
 *   hreflang alternates, Open Graph, Twitter card, manifest, icons and JSON-LD).
 * Rules: Presentation only. Reads the route table generated by scripts/generate-seo.mjs
 *   so alternates never point to a page that does not exist.
 * GOAL: One place that decides how a page is indexed by Google, Bing and AI crawlers.
 */
import Head from 'next/head'
import { useRouter } from 'next/router'

import { navigation } from '@/components/Navigation'
import pageMeta from '@/lib/generated/page-meta.json'
import routes from '@/lib/generated/routes.json'

export const SITE_URL = (process.env.NEXT_PUBLIC_SITE_URL || 'https://www.builderbot.app').replace(/\/$/, '')
const SITE_NAME = 'BuilderBot'
const LOCALES = ['en', 'es', 'pt']
const OG_IMAGE = `${SITE_URL}/assets/og-image-v4.png`
const LOGO = `${SITE_URL}/brand/icon-512.png`
const BOILERPLATE_DESC_RE =
  /Protocol API|something goes wrong while (you work|working) with the API|API de protocolo|algo sale mal mientras trabaja con la API|algo dá errado enquanto você trabalha com a API|what to do to connecting another database/i

const COPY = {
  en: {
    tagline: 'Chatbot for WhatsApp, Telegram and more',
    defaultTitle: 'BuilderBot documentation',
    defaultDescription:
      'Free and open source framework to build chatbots and smart apps for WhatsApp, Telegram, Instagram and other channels. Create your first bot in minutes.',
    locale: 'en_US',
    home: 'Documentation',
  },
  es: {
    tagline: 'Chatbot para WhatsApp, Telegram y más',
    defaultTitle: 'Documentación de BuilderBot',
    defaultDescription:
      'Framework gratuito y open source para crear chatbots y apps inteligentes en WhatsApp, Telegram, Instagram y otros canales. Crea tu primer bot en minutos.',
    locale: 'es_ES',
    home: 'Documentación',
  },
  pt: {
    tagline: 'Chatbot para WhatsApp, Telegram e mais',
    defaultTitle: 'Documentação do BuilderBot',
    defaultDescription:
      'Framework gratuito e open source para criar chatbots e apps inteligentes no WhatsApp, Telegram, Instagram e outros canais. Crie seu primeiro bot em minutos.',
    locale: 'pt_BR',
    home: 'Documentação',
  },
}

/** `/providers/meta` -> `Meta` (fallback title when neither MDX nor nav has one) */
function humanize(route) {
  const segments = route.split('/').filter(Boolean)
  if (!segments.length) return null
  const last = segments[segments.length - 1].replace(/-/g, ' ')
  return last.charAt(0).toUpperCase() + last.slice(1)
}

const GROUP_LABEL = {
  en: 'Docs',
  es: 'Docs',
  pt: 'Docs',
}

/** Path without the locale segment, e.g. `/es/quickstart` -> `/quickstart` */
export function stripLocale(asPath = '/') {
  const [pathPart] = asPath.split(/[?#]/)
  const segments = pathPart.split('/')
  if (LOCALES.includes(segments[1])) {
    const rest = segments.slice(2).join('/')
    return rest ? `/${rest}` : '/'
  }
  return pathPart || '/'
}

/** Breadcrumb trail (Home > Group > Page) for the current route. */
function breadcrumbs({ locale, route, pageTitle, group }) {
  const items = [
    { name: SITE_NAME, item: `${SITE_URL}/${locale}` },
    { name: group || GROUP_LABEL[locale] || 'Docs', item: `${SITE_URL}/${locale}` },
  ]
  if (route !== '/') items.push({ name: pageTitle, item: `${SITE_URL}/${locale}${route}` })
  return {
    '@type': 'BreadcrumbList',
    itemListElement: items.map((entry, index) => ({
      '@type': 'ListItem',
      position: index + 1,
      name: entry.name,
      item: entry.item,
    })),
  }
}

function structuredData({ locale, route, title, description, image, group, mdUrl }) {
  const copy = COPY[locale] ?? COPY.en
  const url = `${SITE_URL}/${locale}${route === '/' ? '' : route}`

  const organization = {
    '@type': 'Organization',
    '@id': `${SITE_URL}/#organization`,
    name: SITE_NAME,
    url: SITE_URL,
    logo: { '@type': 'ImageObject', url: LOGO, width: 512, height: 512 },
    sameAs: [
      'https://github.com/codigoencasa/bot-whatsapp',
      'https://x.com/LeiferMendez',
      'https://link.codigoencasa.com/DISCORD',
    ],
  }

  const website = {
    '@type': 'WebSite',
    '@id': `${SITE_URL}/#website`,
    url: SITE_URL,
    name: SITE_NAME,
    description: copy.defaultDescription,
    inLanguage: locale,
    publisher: { '@id': `${SITE_URL}/#organization` },
    potentialAction: {
      '@type': 'SearchAction',
      target: { '@type': 'EntryPoint', urlTemplate: `${SITE_URL}/${locale}?q={search_term_string}` },
      'query-input': 'required name=search_term_string',
    },
  }

  const techArticle = {
    '@type': 'TechArticle',
    '@id': `${url}#article`,
    headline: title,
    name: title,
    description,
    url,
    image,
    inLanguage: locale,
    isPartOf: { '@id': `${SITE_URL}/#website` },
    publisher: { '@id': `${SITE_URL}/#organization` },
    mainEntityOfPage: { '@type': 'WebPage', '@id': url },
    author: { '@type': 'Organization', name: SITE_NAME, url: SITE_URL },
    encoding: {
      '@type': 'MediaObject',
      contentUrl: mdUrl,
      encodingFormat: 'text/markdown',
    },
  }

  return {
    '@context': 'https://schema.org',
    '@graph': [organization, website, techArticle, breadcrumbs({ locale, route, pageTitle: title, group })],
  }
}

export function Seo({ pageTitle, description, group, type = 'website' }) {
  const router = useRouter()
  const locale = LOCALES.includes(router.asPath.split('/')[1]) ? router.asPath.split('/')[1] : 'en'
  const copy = COPY[locale] ?? COPY.en
  const route = stripLocale(router.asPath) || '/'
  const metaKey = `/${locale}${route === '/' ? '' : route}`
  const generatedMeta = pageMeta[metaKey]

  // MDX pages rarely export a title, so fall back to navigation label or extracted MDX heading
  const navEntry = navigation.find((g) => g.links.some((l) => l.href === route))
  const navPage = navEntry?.links.find((l) => l.href === route)
  const resolvedTitle = pageTitle || navPage?.title || generatedMeta?.title || humanize(route)

  const isHome = route === '/'
  const title = isHome
    ? `${SITE_NAME} — ${copy.tagline}`
    : resolvedTitle
      ? `${resolvedTitle} · ${SITE_NAME}`
      : copy.defaultTitle

  const cleanPassedDesc =
    description && !BOILERPLATE_DESC_RE.test(String(description)) ? String(description) : null
  const desc = String(cleanPassedDesc || generatedMeta?.description || copy.defaultDescription)
    .replace(/\s+/g, ' ')
    .slice(0, 300)
  const image = resolvedTitle
    ? `${SITE_URL}/api/og?title=${encodeURIComponent(resolvedTitle)}`
    : OG_IMAGE
  const canonical = `${SITE_URL}/${locale}${route === '/' ? '' : route}`
  const mdUrl = route === '/' ? `${SITE_URL}/${locale}/index.md` : `${SITE_URL}/${locale}${route}.md`
  const section = group ?? navEntry?.title

  // Only alternate to locales that actually publish this route
  const available = routes[route] || [locale]
  const alternates = available.map((l) => ({
    key: `alt-${l}`,
    rel: 'alternate',
    hrefLang: l,
    href: `${SITE_URL}/${l}${route === '/' ? '' : route}`,
  }))
  if (available.includes('en')) {
    alternates.push({
      key: 'alt-x-default',
      rel: 'alternate',
      hrefLang: 'x-default',
      href: `${SITE_URL}/en${route === '/' ? '' : route}`,
    })
  }

  return (
    <Head>
      <title key="title">{title}</title>
      <meta key="description" name="description" content={desc} />
      <meta key="keywords" name="keywords" content={keywordsFor(route, locale)} />
      <meta key="robots" name="robots" content="index, follow, max-image-preview:large, max-snippet:-1, max-video-preview:-1" />
      <meta key="googlebot" name="googlebot" content="index, follow" />
      <meta key="bingbot" name="bingbot" content="index, follow" />
      <link key="canonical" rel="canonical" href={canonical} />
      <link key="alt-markdown" rel="alternate" type="text/markdown" href={mdUrl} title="Markdown" />
      <link key="describedby-llms" rel="describedby" type="text/markdown" href={`${SITE_URL}/llms.txt`} />
      <link key="describedby-llms-locale" rel="describedby" type="text/markdown" href={`${SITE_URL}/${locale}/llms.txt`} />
      {alternates.map((alt) => (
        <link key={alt.key} {...{ rel: alt.rel, hreflang: alt.hrefLang, href: alt.href }} />
      ))}

      <meta key="og:site_name" property="og:site_name" content={SITE_NAME} />
      <meta key="og:type" property="og:type" content={type} />
      <meta key="og:locale" property="og:locale" content={copy.locale} />
      {available
        .filter((l) => l !== locale)
        .map((l) => (
          <meta key={`og:locale:${l}`} property="og:locale:alternate" content={(COPY[l] ?? COPY.en).locale} />
        ))}
      <meta key="og:url" property="og:url" content={canonical} />
      <meta key="og:title" property="og:title" content={title} />
      <meta key="og:description" property="og:description" content={desc} />
      <meta key="og:image" property="og:image" content={image} />
      <meta key="og:image:secure_url" property="og:image:secure_url" content={image} />
      <meta key="og:image:width" property="og:image:width" content="1200" />
      <meta key="og:image:height" property="og:image:height" content="630" />
      <meta key="og:image:alt" property="og:image:alt" content={title} />
      <meta key="og:image:type" property="og:image:type" content="image/png" />

      <meta key="twitter:card" name="twitter:card" content="summary_large_image" />
      <meta key="twitter:site" name="twitter:site" content="@LeiferMendez" />
      <meta key="twitter:creator" name="twitter:creator" content="@LeiferMendez" />
      <meta key="twitter:title" name="twitter:title" content={title} />
      <meta key="twitter:description" name="twitter:description" content={desc} />
      <meta key="twitter:image" name="twitter:image" content={image} />
      <meta key="twitter:image:alt" name="twitter:image:alt" content={title} />

      <meta key="theme-color" name="theme-color" content="#111214" />
      <meta key="color-scheme" name="color-scheme" content="dark light" />

      <script
        key="jsonld"
        type="application/ld+json"
        dangerouslySetInnerHTML={{
          __html: JSON.stringify(
            structuredData({ locale, route, title, description: desc, image, group: section, mdUrl })
          ).replace(/</g, '\\u003c'),
        }}
      />
    </Head>
  )
}

function keywordsFor(route, locale) {
  const base = [
    'builderbot',
    'whatsapp chatbot',
    'chatbot framework',
    'open source chatbot',
    'nodejs chatbot',
    'baileys',
    'meta whatsapp api',
  ]
  if (locale === 'es') base.push('chatbot whatsapp', 'bot de whatsapp', 'framework chatbot')
  if (locale === 'pt') base.push('chatbot whatsapp', 'bot de whatsapp', 'framework de chatbot')
  const segment = route.split('/').filter(Boolean).pop()
  if (segment && segment !== '/') base.unshift(`${segment.replace(/-/g, ' ')} builderbot`)
  return [...new Set(base)].join(', ')
}

export default Seo
